-- The shop's own product code (D192): `PW-T482913`, the category letter then
-- six random digits. Generated by drizzle-kit, then rewritten by hand: the
-- column cannot be added NOT NULL to a full table, and the code is drawn by
-- the database, so the function, the backfill and both triggers are written
-- here. The unique index comes first so the free-code lookup is an index read.
-- Rows keep their `updated_at`: nothing a person edited changed.
ALTER TABLE "products" ADD COLUMN "sku" text;--> statement-breakpoint
CREATE UNIQUE INDEX "products_sku_key" ON "products" USING btree ("sku");--> statement-breakpoint
-- A free code for a category. Random, so a code says nothing about order or
-- count; on a clash (1 in 900,000 per code already used) it draws again. Two
-- inserts drawing the same free code at the same instant would meet the
-- unique index and one would fail: accepted, it is that rare.
CREATE FUNCTION products_new_sku(cat product_category) RETURNS text
LANGUAGE plpgsql VOLATILE AS $$
DECLARE
  candidate text;
BEGIN
  LOOP
    candidate := 'PW-'
      || CASE cat WHEN 'tires' THEN 'T' WHEN 'wheels' THEN 'W' ELSE 'A' END
      || (100000 + floor(random() * 900000))::int::text;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM products WHERE sku = candidate);
  END LOOP;
  RETURN candidate;
END;
$$;
--> statement-breakpoint
-- One UPDATE per row, so each draw sees the codes given before it.
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT id, category FROM products ORDER BY random() LOOP
    UPDATE products SET sku = products_new_sku(r.category) WHERE id = r.id;
  END LOOP;
END;
$$;
--> statement-breakpoint
ALTER TABLE "products" ALTER COLUMN "sku" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "products" ADD CONSTRAINT "products_sku_format" CHECK ("products"."sku" ~ '^PW-[TWA][1-9][0-9]{5}$' and substr("products"."sku", 4, 1) = case "products"."category" when 'tires' then 'T' when 'wheels' then 'W' else 'A' end);--> statement-breakpoint
-- An insert that leaves the code out gets one. NOT NULL is checked after
-- BEFORE triggers, so the app's inserts (which send DEFAULT) and code already
-- live that knows nothing of the column both work.
CREATE FUNCTION products_fill_sku() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.sku IS NULL THEN
    NEW.sku := products_new_sku(NEW.category);
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER products_fill_sku
  BEFORE INSERT ON "products"
  FOR EACH ROW EXECUTE FUNCTION products_fill_sku();
--> statement-breakpoint
-- A code is never rewritten, like a slug: a printed quote or an email that
-- names it must still find the product.
CREATE FUNCTION products_keep_sku() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.sku IS DISTINCT FROM OLD.sku THEN
    RAISE EXCEPTION 'products.sku is never changed (%)', OLD.sku
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER products_keep_sku
  BEFORE UPDATE OF sku ON "products"
  FOR EACH ROW EXECUTE FUNCTION products_keep_sku();
